#!/usr/bin/env bash
# =========================================== # Secure RAG - System Health Check # =========================================== set -euo pipefail  RED='\033[0;31m' GREEN='\033[0;32m' YELLOW='\033[1;33m' NC='\033[0m'  check() {   local name=$1   local cmd=$2   if eval "$cmd" > /dev/null 2>&1; then     echo -e "${GREEN}✓${NC} $name"     return 0   else     echo -e "${RED}✗${NC} $name"     return 1   fi }  echo "=== Secure RAG Health Check ===" echo ""  FAILURES=0  # Docker services check "Docker daemon" "docker info" || ((FAILURES++)) check "PostgreSQL" "docker compose exec -T postgres pg_isready -U secure_rag_user" || ((FAILURES++)) check "Redis" "docker compose exec -T redis redis-cli ping" || ((FAILURES++)) check "ChromaDB" "docker compose exec -T chromadb curl -sf http://localhost:8000/api/v1/heartbeat" || ((FAILURES++)) check "Backend API" "curl -sf http://localhost:8000/health" || ((FAILURES++)) check "Frontend" "curl -sf http://localhost:3000/" || ((FAILURES++)) check "Nginx" "curl -sf http://localhost:80/" || ((FAILURES++)) check "Celery Worker" "docker compose exec -T celery_worker celery -A celery_worker.celery_app inspect ping 2>/dev/null" || ((FAILURES++))  echo "" if [ $FAILURES -eq 0 ]; then   echo -e "${GREEN}All services healthy${NC}" else   echo -e "${YELLOW}$FAILURES service(s) unhealthy${NC}" fi  exit $FAILURES
